// LoadPlaidItem loads the plaidAccountLink's PlaidItem into the .R struct
func (os PlaidAccountLinkSlice) LoadPlaidItem(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	plaidItems, err := os.PlaidItem(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.PlaidItem = nil
		o.R.Loaded.PlaidItem = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	plaidAccountLinkByKey := make(map[uuid.UUID][]*PlaidAccountLink, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		plaidAccountLinkByKey[o.PlaidItemID] = append(plaidAccountLinkByKey[o.PlaidItemID], o)
	}

	for _, rel := range plaidItems {

		owners, ok := plaidAccountLinkByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.PlaidItem != nil {
				continue
			}

			rel.R.PlaidAccountLinks = append(rel.R.PlaidAccountLinks, o)

			o.R.PlaidItem = rel

		}
	}

	return nil
}

type plaidAccountLinkJoins[Q dialect.Joinable] struct {
	typ       string
	Account   modAs[Q, accountColumns]
	PlaidItem modAs[Q, plaidItemColumns]
}

func (j plaidAccountLinkJoins[Q]) aliasedAs(alias string) plaidAccountLinkJoins[Q] {
	return buildPlaidAccountLinkJoins[Q](buildPlaidAccountLinkColumns(alias), j.typ)
}

func buildPlaidAccountLinkJoins[Q dialect.Joinable](cols plaidAccountLinkColumns, typ string) plaidAccountLinkJoins[Q] {
	return plaidAccountLinkJoins[Q]{
		typ: typ,
		Account: modAs[Q, accountColumns]{
			c: Accounts.Columns,
			f: func(to accountColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Accounts.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.AccountID),
					))
				}

				return mods
			},
		},
		PlaidItem: modAs[Q, plaidItemColumns]{
			c: PlaidItems.Columns,
			f: func(to plaidItemColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PlaidItems.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.PlaidItemID),
					))
				}

				return mods
			},
		},
	}
}
